<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lighthouse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --preset=desktop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --throttling-method=provided</span></span>
